 if d.test_id is null or d.revision<>1 or d.current_version is not null or d.definition is distinct from '{"id":"boundaries","title":"Границы и приватность","description":"Условия общения и раскрытия сведений. Ответы не устанавливают и не отменяют твои реальные границы. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"discussion","title":"Обсуждение комфорта","low":"В ответах меньше предпочтения подробно обсуждать условия. При этом любое действие требует отдельного согласия; молчание не считается разрешением.","mid":"Может подходить короткое обсуждение важных условий. Уточнять их можно в любой момент.","high":"В ответах важен явный разговор о комфорте. Можно заранее согласовать слова для паузы и остановки."},{"id":"privacy","title":"Выбор раскрытия","low":"Сейчас выборочная открытость может быть комфортнее. Результат ничего не публикует: отдельные сведения раскрываешь только ты.","mid":"Степень открытости может зависеть от темы и человека. Удобно выбирать сведения по отдельности.","high":"В ответах важно контролировать раскрытие. Можно выдавать частичный доступ на срок и отзывать его."}],"questions":[{"id":"discussion-1","prompt":"Мне удобно словами обсуждать, что подходит, а что нет.","dimension":"discussion","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"discussion-2","prompt":"Я хочу, чтобы изменения плана сначала обсуждались.","dimension":"discussion","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит"