 if d.test_id is null or d.revision<>1 or d.current_version is not null or d.definition is distinct from '{"id":"pace","title":"Темп и готовность","description":"Какой темп знакомства и новых шагов может быть комфортен сейчас. Любой вопрос можно пропустить. Это опросник для размышления, а не научная диагностика.","dimensions":[{"id":"gradual","title":"Постепенность","low":"В ответах меньше потребности в длинной подготовке. Даже быстрый темп требует взаимной готовности и возможности остановки.","mid":"Темп может зависеть от ситуации. Удобно договориться о небольшом следующем шаге без обещания продолжения.","high":"В ответах важна постепенность. Можно начать с беседы и дать себе время без сравнений с чужим темпом."},{"id":"checkin","title":"Проверка готовности","low":"Сейчас частые уточнения могут быть менее удобны. Это не означает согласия заранее: готовность нужно уточнять перед конкретным действием.","mid":"Может подходить проверка готовности в важных точках. Можно обсудить удобный способ задавать вопросы.","high":"В ответах важны регулярные уточнения готовности. Можно согласовать их так, чтобы они поддерживали комфорт, а не создавали давление."}],"questions":[{"id":"gradual-1","prompt":"Мне комфортнее узнавать человека постепенно.","dimension":"gradual","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id":"gradual-2","prompt":"Перед новым шагом мне хочется время на обдумывание.","dimension":"gradual","kind":"scale","options":[{"id":"answer-0","label":"Сейчас не подходит","score":0},{"id":"answer-1","label":"Скорее не подходит","score":1},{"id":"answer-2","label":"Зависит от ситуации","score":2},{"id":"answer-3","label":"Скорее подходит","score":3},{"id":"answer-4","label":"Сейчас подходит","score":4}]},{"id"